
.npc-panel {
  background-color: var(--c-surface);
  padding: 8px 10px;
  margin-bottom: 10px;
  border-radius: 2px;
}

.npc-header {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
  padding-bottom: 6px;
  border-bottom: 1px solid var(--c-background);
  flex-wrap: wrap;
}

.npc-name {
  color: var(--c-primary);
  font-weight: bold;
  font-size: 0.95rem;
}

.npc-tag {
  color: var(--c-accent);
  font-size: 0.75rem;
  background-color: var(--c-background);
  padding: 1px 6px;
  border-radius: 2px;
}

.npc-age {
  color: var(--c-text-muted);
  font-size: 0.75rem;
}

.npc-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 6px;
}

.body-grid {
  border-top: 1px dashed var(--c-background);
  padding-top: 6px;
}

.npc-field {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.field-label {
  color: var(--c-text-muted);
  font-size: 0.7rem;
  flex-shrink: 0;
}

.field-value {
  color: var(--c-text-primary);
  font-size: 0.8rem;
  line-height: 1.35;
}

.npc-personality {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 6px;
  padding-top: 6px;
  border-top: 1px dashed var(--c-background);
}

@media (max-width: 500px) {
  .npc-grid {
    grid-template-columns: 1fr;
  }
}
