
.status-bar {
  width: 100%;
  max-width: 680px;
  background-color: var(--c-background);
  border: 1px solid var(--c-surface);
  border-left: 3px solid var(--c-primary);
  font-family: var(--font-main);
  color: var(--c-text-primary);
  font-size: 13px;
  line-height: 1.4;
  margin: 0 auto;
}

.header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  cursor: pointer;
  user-select: none;
  border-bottom: 1px solid var(--c-surface);
  transition: background-color 0.15s;

  &:hover {
    background-color: var(--c-surface);
  }
}

.header-left {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
}

.header-time {
  font-family: var(--font-mono);
  color: var(--c-text-muted);
  font-size: 0.85rem;
}

.header-divider {
  color: var(--c-text-muted);
  opacity: 0.5;
}

.header-loc {
  color: var(--c-primary);
  font-weight: bold;
}

.header-loc-empty {
  color: var(--c-text-muted);
  font-weight: normal;
}

.header-right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.header-name {
  color: var(--c-text-primary);
  font-weight: bold;
}

.header-toggle {
  color: var(--c-text-muted);
  font-size: 0.7rem;
  transition: transform 0.2s;
}

.header-toggle-open {
  transform: rotate(180deg);
}

.expand-area {
  padding: 10px 12px;
}

.scene-status {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--c-surface);
}

.scene-label {
  color: var(--c-text-muted);
  font-size: 0.75rem;
  background-color: var(--c-surface);
  padding: 2px 6px;
  border-radius: 2px;
}

.scene-value {
  color: var(--c-accent);
  font-size: 0.85rem;
}

.npc-empty {
  text-align: center;
  padding: 20px 0;
}

.npc-empty-text {
  color: var(--c-text-muted);
  font-size: 0.8rem;
}

.actions {
  display: flex;
  gap: 8px;
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-surface);
  flex-wrap: wrap;
}

.action-item {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1;
  min-width: 120px;
}

.action-tag {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 18px;
  background-color: var(--c-accent);
  color: var(--c-background);
  font-size: 0.7rem;
  font-weight: bold;
  border-radius: 2px;
  flex-shrink: 0;
}

.action-text {
  color: var(--c-text-primary);
  font-size: 0.8rem;
  line-height: 1.3;
}

@media (max-width: 500px) {
  .header {
    flex-direction: column;
    align-items: flex-start;
    gap: 4px;
  }

  .actions {
    flex-direction: column;
  }

  .action-item {
    min-width: auto;
  }
}
